15	bool range_size_first_comparator::operator()(const memory_range &mr1, const memory_range &mr2) const noexcept
16	{
17	    if (mr1.size != mr2.size) {
18	        return mr1.size < mr2.size;
19	    }
20	
21	    return mr1.offset < mr2.offset;
22	}
