24	memory_manager::memory_manager(void *base, uint64_t size) noexcept : base_{reinterpret_cast<uint8_t *>(base)}, size_{size}
25	{
26	    pthread_spin_init(&spinlock_, 0);
27	    address_idle_tree_[0] = size;
28	    size_idle_tree_.insert({0, size});
29	}
