36	void *memory_manager::allocate(uint64_t size) noexcept
37	{
38	    if (size == 0 || size > g_state.heap_size) {
39	        SHM_LOG_ERROR("cannot allocate with size " << size);
40	        return nullptr;
41	    }
42	
43	    auto aligned_size = allocated_size_align_up(size);
44	    memory_range anchor{0, aligned_size};
45	
46	    pthread_spin_lock(&spinlock_);
47	    auto size_pos = size_idle_tree_.lower_bound(anchor);
48	    if (size_pos == size_idle_tree_.end()) {
49	        pthread_spin_unlock(&spinlock_);
50	        SHM_LOG_ERROR("cannot allocate with size: " << size);
51	        return nullptr;
52	    }
53	
54	    auto target_offset = size_pos->offset;
55	    auto target_size = size_pos->size;
56	    auto addr_pos = address_idle_tree_.find(target_offset);
57	    if (addr_pos == address_idle_tree_.end()) {
58	        pthread_spin_unlock(&spinlock_);
59	        SHM_LOG_ERROR("offset(" << target_offset << ") size(" << target_size << ") in size tree, not in address tree.");
60	        return nullptr;
61	    }
62	
63	    size_idle_tree_.erase(size_pos);
64	    address_idle_tree_.erase(addr_pos);
65	    address_used_tree_.emplace(target_offset, aligned_size);
66	    if (target_size > aligned_size) {
67	        memory_range left{target_offset + aligned_size, target_size - aligned_size};
68	        address_idle_tree_.emplace(left.offset, left.size);
69	        size_idle_tree_.emplace(left);
70	    }
71	    pthread_spin_unlock(&spinlock_);
72	
73	    return base_ + target_offset;
74	}
75	
76	void *memory_manager::aligned_allocate(uint64_t alignment, uint64_t size) noexcept
77	{
78	    if (size == 0 || alignment == 0 || size > g_state.heap_size) {
79	        SHM_LOG_ERROR("invalid input, align=" << alignment << ", size=" << size);
80	        return nullptr;
81	    }
82	
83	    if ((alignment & (alignment - 1UL)) != 0) {
84	        SHM_LOG_ERROR("alignment should be power of 2, but real " << alignment);
85	        return nullptr;
86	    }
87	
88	    uint64_t head_skip = 0;
89	    auto aligned_size = allocated_size_align_up(size);
90	    memory_range anchor{0, aligned_size};
91	
92	    pthread_spin_lock(&spinlock_);
93	    auto size_pos = size_idle_tree_.lower_bound(anchor);
94	    while (size_pos != size_idle_tree_.end() && !alignment_matches(*size_pos, alignment, aligned_size, head_skip)) {
95	        ++size_pos;
96	    }
97	
98	    if (size_pos == size_idle_tree_.end()) {
99	        pthread_spin_unlock(&spinlock_);
100	        SHM_LOG_ERROR("cannot allocate with size: " << size << ", alignment: " << alignment);
101	        return nullptr;
102	    }
103	
104	    auto target_offset = size_pos->offset;
105	    auto target_size = size_pos->size;
106	    memory_range result_range{size_pos->offset + head_skip, aligned_size};
107	    size_idle_tree_.erase(size_pos);
108	
109	    if (head_skip > 0) {
110	        size_idle_tree_.emplace(memory_range{target_offset, head_skip});
111	        address_idle_tree_.emplace(target_offset, head_skip);
112	    }
113	
114	    if (head_skip + aligned_size < target_size) {
115	        memory_range leftMR{target_offset + head_skip + aligned_size, target_size - head_skip - aligned_size};
116	        size_idle_tree_.emplace(leftMR);
117	        address_idle_tree_.emplace(leftMR.offset, leftMR.size);
118	    }
119	
120	    address_used_tree_.emplace(result_range.offset, result_range.size);
121	    pthread_spin_unlock(&spinlock_);
122	
123	    return base_ + result_range.offset;
124	}
