126	bool memory_manager::change_size(void *address, uint64_t size) noexcept
127	{
128	    auto u8a = reinterpret_cast<uint8_t *>(address);
129	    if (u8a < base_ || u8a >= base_ + size_) {
130	        SHM_LOG_ERROR("release invalid address " << address);
131	        return false;
132	    }
133	
134	    if (size == 0) {
135	        release(address);
136	        return true;
137	    }
138	
139	    auto offset = u8a - base_;
140	    pthread_spin_lock(&spinlock_);
141	    auto pos = address_used_tree_.find(offset);
142	    if (pos == address_used_tree_.end()) {
143	        pthread_spin_unlock(&spinlock_);
144	        SHM_LOG_ERROR("change size for address " << address << " not allocated.");
145	        return false;
146	    }
147	
148	    // size不变
149	    if (pos->second == size) {
150	        pthread_spin_unlock(&spinlock_);
151	        return true;
152	    }
153	
154	    // 缩小size
155	    if (pos->second > size) {
156	        reduce_size_in_lock(pos, size);
157	        pthread_spin_unlock(&spinlock_);
158	        return true;
159	    }
160	
161	    // 扩大size
162	    auto success = expend_size_in_lock(pos, size);
163	    pthread_spin_unlock(&spinlock_);
164	
165	    return success;
166	}
