168	int32_t memory_manager::release(void *address) noexcept
169	{
170	    auto u8a = reinterpret_cast<uint8_t *>(address);
171	    if (u8a < base_ || u8a >= base_ + size_) {
172	        SHM_LOG_ERROR("release invalid address " << address);
173	        return -1;
174	    }
175	
176	    auto offset = u8a - base_;
177	    pthread_spin_lock(&spinlock_);
178	    auto pos = address_used_tree_.find(offset);
179	    if (pos == address_used_tree_.end()) {
180	        pthread_spin_unlock(&spinlock_);
181	        SHM_LOG_ERROR("release address " << address << " not allocated.");
182	        return -1;
183	    }
184	
185	    auto size = pos->second;
186	    uint64_t final_offset = static_cast<uint64_t>(offset);
187	    uint64_t final_size = size;
188	    address_used_tree_.erase(pos);
189	
190	    auto prev_addr_pos = address_idle_tree_.lower_bound(offset);
191	    if (prev_addr_pos != address_idle_tree_.begin()) {
192	        --prev_addr_pos;
193	        if (prev_addr_pos != address_idle_tree_.end() &&
194	            prev_addr_pos->first + prev_addr_pos->second == static_cast<uint64_t>(offset)) {
195	            // 合并前一个range
196	            final_offset = prev_addr_pos->first;
197	            final_size += prev_addr_pos->second;
198	
199	            auto prev_addr_range = *prev_addr_pos;
200	            address_idle_tree_.erase(prev_addr_pos);
201	            size_idle_tree_.erase(memory_range{prev_addr_range.first, prev_addr_range.second});
202	        }
203	    }
204	
205	    auto next_addr_pos = address_idle_tree_.find(offset + size);
206	    if (next_addr_pos != address_idle_tree_.end()) {  // 合并后一个range
207	        uint64_t next_addr = next_addr_pos->first;
208	        uint64_t next_size = next_addr_pos->second;
209	        final_size += next_size;
210	        address_idle_tree_.erase(next_addr_pos);
211	        size_idle_tree_.erase(memory_range{next_addr, next_size});
212	    }
213	    address_idle_tree_.emplace(final_offset, final_size);
214	    size_idle_tree_.emplace(memory_range{final_offset, final_size});
215	    pthread_spin_unlock(&spinlock_);
216	
217	    return 0;
218	}
219	
220	bool memory_manager::allocated_size(void *address, uint64_t &size) const noexcept
221	{
222	    auto u8a = reinterpret_cast<uint8_t *>(address);
223	    if (u8a < base_ || u8a >= base_ + size_) {
224	        SHM_LOG_ERROR("release invalid address " << address);
225	        return false;
226	    }
227	
228	    auto offset = u8a - base_;
229	    bool exist = false;
230	    pthread_spin_lock(&spinlock_);
231	    auto pos = address_used_tree_.find(offset);
232	    if (pos != address_used_tree_.end()) {
233	        exist = true;
234	        size = pos->second;
235	    }
236	    pthread_spin_unlock(&spinlock_);
237	
238	    return exist;
239	}
240	
241	uint64_t memory_manager::allocated_size_align_up(uint64_t input_size) noexcept
242	{
243	    constexpr uint64_t align_size = 16UL;
244	    constexpr uint64_t align_size_mask = ~(align_size - 1UL);
245	    return (input_size + align_size - 1UL) & align_size_mask;
246	}
247	
248	bool memory_manager::alignment_matches(const memory_range &mr, uint64_t alignment, uint64_t size,
249	                                    uint64_t &head_skip) noexcept
250	{
251	    if (mr.size < size) {
252	        return false;
253	    }
254	
255	    if ((mr.offset & (alignment - 1UL)) == 0UL) {
256	        head_skip = 0;
257	        return true;
258	    }
259	
260	    auto aligned_offset = ((mr.offset + alignment - 1UL) & (~(alignment - 1UL)));
261	    head_skip = aligned_offset - mr.offset;
262	    return mr.size >= size + head_skip;
263	}
264	
265	void memory_manager::reduce_size_in_lock(const std::map<uint64_t, uint64_t>::iterator &pos, uint64_t new_size) noexcept
266	{
267	    auto offset = pos->first;
268	    auto old_size = pos->second;
269	    pos->second = new_size;
270	    auto next_addr_pos = address_idle_tree_.find(offset + old_size);
271	    if (next_addr_pos == address_idle_tree_.end()) {
272	        address_idle_tree_.emplace(offset + new_size, old_size - new_size);
273	        size_idle_tree_.emplace(memory_range{offset + new_size, old_size - new_size});
274	    } else {
275	        auto next_size_pos = size_idle_tree_.find(memory_range{next_addr_pos->first, next_addr_pos->second});
276	        size_idle_tree_.erase(next_size_pos);
277	        next_addr_pos->second += (old_size - new_size);
278	        size_idle_tree_.emplace(memory_range{next_addr_pos->first, next_addr_pos->second});
279	    }
280	}
281	
282	bool memory_manager::expend_size_in_lock(const std::map<uint64_t, uint64_t>::iterator &pos, uint64_t new_size) noexcept
283	{
284	    auto offset = pos->first;
285	    auto old_size = pos->second;
286	    auto delta = new_size - old_size;
287	
288	    auto next_addr_pos = address_idle_tree_.find(offset + old_size);
289	    if (next_addr_pos == address_idle_tree_.end() || next_addr_pos->second < delta) {
290	        return false;
291	    }
292	
293	    pos->second = new_size;
294	    auto next_size_pos = size_idle_tree_.find(memory_range{next_addr_pos->first, next_addr_pos->second});
295	    if (next_addr_pos->second == delta) {
296	        size_idle_tree_.erase(next_size_pos);
297	        address_idle_tree_.erase(next_addr_pos);
298	    } else {
299	        size_idle_tree_.erase(next_size_pos);
300	        next_addr_pos->second -= delta;
301	        size_idle_tree_.emplace(memory_range{next_addr_pos->first, next_addr_pos->second});
302	    }
303	
304	    return true;
305	}
